// Browser-local, finite simulated liquidity. All prices/escrow use integer coin cents.
const cents=n=>Math.round(n*100),money=n=>n/100,open=o=>o.remaining>0&&o.status==='open';
export function ensureExchange(s){if(s.exchange?.version===1)return s.exchange;let seq=0;const orders=[];for(const o of s.offers||[]){const base=cents(o.price);for(const [side,total]of [['sell',o.stock],['buy',o.buy]])for(let i=0;i<3;i++){const quantity=Math.floor(total/3)+(i<total%3?1:0);if(!quantity)continue;orders.push({id:'demo-'+(++seq),seq,good:o.good,side,price:side==='sell'?base+Math.max(1,Math.round(base*.025))*i:Math.max(1,Math.round(base*(.94-i*.025))),quantity,remaining:quantity,owner:'demo',maker:o.seller,status:'open',type:'limit'});}}return s.exchange={version:1,seq,orders,trades:[]};}
export function depth(s,good){const e=ensureExchange(s),sort=side=>e.orders.filter(o=>o.good===good&&o.side===side&&open(o)).sort((a,b)=>(side==='buy'?b.price-a.price:a.price-b.price)||a.seq-b.seq);return {bids:sort('buy'),asks:sort('sell')};}
function transaction(s,fn){const copy=structuredClone(s),result=fn(copy);Object.assign(s,copy);return result;}
export function placeOrder(s,{good,side,type='limit',quantity,price}){return transaction(s,t=>{
 const e=ensureExchange(t);if(!t.offers?.some(o=>o.good===good)||!['buy','sell'].includes(side)||!['limit','market'].includes(type))throw Error('Choose a valid market, side and order type.');if(!Number.isInteger(quantity)||quantity<1||quantity>1000)throw Error('Quantity must be a whole number from 1 to 1000.');const p=cents(Number(price));if(type==='limit'&&(!Number.isFinite(Number(price))||p<1||p>10000000||Math.abs(Number(price)*100-p)>.00001))throw Error('Use a positive limit price with at most two decimals.');
 const eligible=o=>o.good===good&&o.side!==side&&open(o)&&(type==='market'||(side==='buy'?o.price<=p:o.price>=p));if(e.orders.some(o=>o.owner==='player'&&eligible(o)))throw Error('Cancel your opposite crossing order first; self-trades are disabled.');const matches=e.orders.filter(o=>o.owner!=='player'&&eligible(o)).sort((a,b)=>(side==='buy'?a.price-b.price:b.price-a.price)||a.seq-b.seq);
 let left=quantity,quote=0;for(const m of matches){const n=Math.min(left,m.remaining);quote+=m.price*n;left-=n;if(!left)break;}if(type==='market'&&left===quantity)throw Error('No matching orders are available. Try a limit order.');const reserve=side==='buy'?(type==='limit'?p*quantity:quote):0;if(side==='buy'&&cents(t.coins)<reserve)throw Error('Not enough available farm coins for this order.');if(side==='sell'&&(t.inventory[good]||0)<quantity)throw Error('Not enough available goods. Cancel reserved orders to release stock.');if(side==='buy')t.coins=money(cents(t.coins)-reserve);else t.inventory[good]-=quantity;
 const order={id:'order-'+(++e.seq),seq:e.seq,good,side,type,price:type==='limit'?p:0,quantity,remaining:quantity,owner:'player',status:'open',lockedCoins:reserve};e.orders.push(order);let spent=0,fee=0;
 for(const m of matches){if(!order.remaining)break;const n=Math.min(order.remaining,m.remaining),gross=m.price*n,tradeFee=side==='sell'?Math.ceil(gross*.05):0;order.remaining-=n;m.remaining-=n;if(!m.remaining)m.status='filled';if(side==='buy'){t.inventory[good]=(t.inventory[good]||0)+n;if(type==='limit'){order.lockedCoins-=p*n;t.coins=money(cents(t.coins)+(p-m.price)*n);}else order.lockedCoins-=gross;}else{t.coins=money(cents(t.coins)+gross-tradeFee);fee+=tradeFee;}spent+=gross;e.trades.unshift({id:'fill-'+(++e.seq),good,price:m.price,quantity:n,side,day:t.day,orderId:order.id,fee:tradeFee});}
 if(type==='market'&&order.remaining){if(side==='sell')t.inventory[good]+=order.remaining;order.status='partial-cancelled';}else order.status=order.remaining?'open':'filled';if(type==='market')order.lockedCoins=0;e.trades=e.trades.slice(0,100);return {orderId:order.id,filled:quantity-order.remaining,remaining:order.remaining,status:order.status,total:money(spent),fee:money(fee)};
 });}
export function cancelOrder(s,id){return transaction(s,t=>{const e=ensureExchange(t),o=e.orders.find(o=>o.id===id&&o.owner==='player'&&open(o));if(!o)throw Error('This order is no longer open.');if(o.side==='buy'){t.coins=money(cents(t.coins)+o.lockedCoins);o.lockedCoins=0;}else t.inventory[o.good]=(t.inventory[o.good]||0)+o.remaining;o.status='cancelled';return o;});}
export function reserved(s){const e=ensureExchange(s);return {coins:money(e.orders.filter(o=>o.owner==='player'&&open(o)&&o.side==='buy').reduce((n,o)=>n+o.lockedCoins,0)),goods:e.orders.filter(o=>o.owner==='player'&&open(o)&&o.side==='sell').reduce((a,o)=>{a[o.good]=(a[o.good]||0)+o.remaining;return a;},{})};}
